{
  "field_accounts": {
    "Q22B": "Asks approval of 'the army comes in to govern the country' as a mode of governing; response act is approve/disapprove rating (ordinal 1-5), actor is the army, referent is military governance of the country.",
    "Q29B": "Forces a choice: 'armed forces should never intervene in the country's political process' versus 'legitimate for the armed forces to take control of government when elected leaders abuse power'; response act is two-statement agreement (1-5 including 'Agree with neither'), actor is armed forces, referent is military intervention/control conditioned on abuse of power.",
    "Q28": "Forces choice between president not bound by laws versus 'president must always obey the laws and the courts'; actor is the president, referent is executive subordination to law/courts, not military rule.",
    "Q48A": "Nominally asks 'Who should be responsible for' ensuring 'members of Parliament do their jobs'; response act is selecting an accountability agent (President/Executive, Parliament/local council, party, voters, no one), referent is MP accountability.",
    "Q48B": "Same accountability-agent response structure but referent is 'the [president] does [his] job'; actor held accountable is the president, not MPs.",
    "Q63B": "Asks agreement that it is 'justified for the government to temporarily limit democracy or democratic freedoms' via police/security enforcement of health mandates; response act is agree/disagree (ordinal 1-5), referent is emergency-limited freedoms, includes 'Not applicable (COV1=0, 8 or 9)'."
  },
  "observed_contrasts": [
    "Q22B and Q29B both concern military role in politics but differ in response act: Q22B is a single-option approve/disapprove rating, while Q29B is a forced statement-choice with 'Agree with neither'.",
    "Q22B asks about 'the army comes in to govern' unconditionally; Q29B conditions legitimacy on 'elected leaders abuse power for their own ends', so scope and condition differ.",
    "Q28 also uses the forced statement-choice format like Q29B but the actor is 'the [president]' and referent is legal constraint, not armed forces.",
    "Q48A and Q48B share identical response-option sets and 'Who should be responsible for' stem but swap the accountable actor: 'members of Parliament' vs 'the [president]'.",
    "Q48A/Q48B are nominal agent-selection items, unlike the ordinal approve/agree scales of Q22B, Q28, Q29B, Q63B.",
    "Q63B carries 'Not applicable (COV1=0, 8 or 9)' indicating a skip/eligibility dependency absent from Q22B, Q28, Q29B, Q48A, Q48B.",
    "Q48A uniquely includes 'Not asked in Burkina Faso after 4th of October', a country/time-specific non-administration flag not present in Q48B."
  ],
  "candidate_relations": [
    {
      "fields": ["Q22B", "Q29B"],
      "false_merge_label": "military intervention in politics",
      "actual_difference": "Q22B: approve/disapprove of army governing; Q29B: forced choice on armed forces control conditioned on abuse of power. Different response structures and conditional framing."
    },
    {
      "fields": ["Q48A", "Q48B"],
      "false_merge_label": "who should be responsible for elected officials doing their jobs",
      "actual_difference": "Q48A referent is members of Parliament; Q48B referent is the president. Same options but distinct accountability targets."
    },
    {
      "fields": ["Q28", "Q29B"],
      "false_merge_label": "executive constraint / rule of law",
      "actual_difference": "Q28 concerns presidential obedience to law/courts; Q29B concerns military takeover legitimacy. Shared forced-choice format but different actor and referent."
    }
  ],
  "source_limits": [
    "Metadata only: no respondent frequencies, cross-field co-occurrence, or causal inference is supported.",
    "Administration is known only as supplied; Q48A shows country exclusion flags, and Q63B shows a COV1-based not-applicable condition, so comparability across items cannot be assumed.",
    "Q28 includes '94 = Not asked in the country', indicating item availability varies; no claim about which countries asked it.",
    "Module guesses ('demographic_core' for Q22B/Q28/Q29B/Q63B) are metadata labels, not analytic guarantees.",
    "Ordinal response scales across items are not guaranteed to be psychometrically equivalent."
  ],
  "foil_transfer_check": [
    {
      "source_field": "Q22B",
      "foil_field": "Q29B",
      "transfer": "Do not transfer the single-item approve scale interpretation to Q29B; Q29B requires resolving a two-statement tradeoff and explicitly allows 'Agree with neither'.",
      "quote": "the army comes in to govern the country"
    },
    {
      "source_field": "Q48A",
      "foil_field": "Q48B",
      "transfer": "Do not transfer MP-accountability interpretation to the president item; the agent named changes even though options match.",
      "quote": "making sure that, once elected, the [president] does [his] job"
    },
    {
      "source_field": "Q28",
      "foil_field": "Q29B",
      "transfer": "Do not treat Q28's rule-of-law constraint as measuring military intervention; Q28 actor is the president.",
      "quote": "The [president] must always obey the laws and the courts"
    },
    {
      "source_field": "Q63B",
      "foil_field": "Q22B",
      "transfer": "Do not transfer generic approve/disapprove governance ratings to Q63B; its condition is a public health emergency and includes eligibility filtering.",
      "quote": "Not applicable (COV1=0, 8 or 9)"
    }
  ]
}
